{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "ACTION_LOG.A01",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A entrega do redutor em D20 continua correta, mas a folga desse fornecedor mudou com o novo cronograma."
    },
    {
      "trecho_id": "ACTION_LOG.A02",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "revisão 1",
          "motivo": "premissa_alterada",
          "correto_seria": "revisão 2"
        },
        {
          "citacao": "Prazo: D10.",
          "motivo": "valor_divergente",
          "correto_seria": "Prazo: D13."
        }
      ],
      "observacao": "O detalhamento termina em D13 e gera o desenho CAD revisão 2."
    },
    {
      "trecho_id": "ACTION_LOG.A03",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Prazo: D14.",
          "motivo": "valor_divergente",
          "correto_seria": "Prazo: D17."
        }
      ],
      "observacao": "A análise estrutural termina em D17 e o Design Freeze passa para D17."
    },
    {
      "trecho_id": "ACTION_LOG.A04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a partir de D25",
          "motivo": "valor_divergente",
          "correto_seria": "a partir de D28"
        },
        {
          "citacao": "até a validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "até a validação em D38"
        },
        {
          "citacao": "o protótipo estará disponível em D26.",
          "motivo": "valor_divergente",
          "correto_seria": "o protótipo estará disponível em D28."
        }
      ],
      "observacao": "Após a mudança, o protótipo fica disponível em D28 e a validação termina em D38."
    },
    {
      "trecho_id": "ACTION_LOG.A05",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A franquia até D40 e a tarifa de R$ 300 por dia excedente continuam corretas, mas o novo cronograma leva a liberação a D43 e aciona custo excedente."
    },
    {
      "trecho_id": "ACTION_LOG.A06",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "As datas de entrega das peças e a parcela de frete compartilhado não mudam; contudo, o período de compras e fabricação passa para D17–D23."
    },
    {
      "trecho_id": "RISK_REGISTER.R01",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "não tem folga",
          "motivo": "valor_divergente",
          "correto_seria": "tem 3 dias de folga"
        },
        {
          "citacao": "qualquer atraso empurraria a montagem para depois de D20 e a liberação para depois de D40.",
          "motivo": "premissa_alterada",
          "correto_seria": "atrasos de até 3 dias não deslocariam a montagem; atrasos superiores a 3 dias a deslocariam para depois de D23 e levariam a liberação para depois de D43."
        }
      ],
      "observacao": "A montagem passa a começar em D23 e a liberação de engenharia termina em D43."
    },
    {
      "trecho_id": "RISK_REGISTER.R02",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "depois de D20",
          "motivo": "valor_divergente",
          "correto_seria": "depois de D23"
        }
      ],
      "observacao": "A placa e o chicote têm entrega em D19 e folga de 4 dias até o início da montagem em D23. Uma entrega após D20, mas até D23, não deslocaria a montagem."
    },
    {
      "trecho_id": "RISK_REGISTER.R03",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O risco continua ligado ao cronograma: a validação prevista passa para D38, e dias adicionais além da franquia continuam sujeitos aos custos indicados."
    },
    {
      "trecho_id": "RISK_REGISTER.R04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "sairia de D14",
          "motivo": "valor_divergente",
          "correto_seria": "sairia de D17"
        }
      ],
      "observacao": "O Design Freeze previsto após a análise estrutural passa de D14 para D17."
    },
    {
      "trecho_id": "RISK_REGISTER.R05",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "terminaria em D31",
          "motivo": "valor_divergente",
          "correto_seria": "terminaria em D34"
        },
        {
          "citacao": "validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "validação em D38"
        }
      ],
      "observacao": "O ensaio de vedação termina normalmente em D31; se repetido integralmente por mais 3 dias, termina em D34, antes da validação em D38."
    },
    {
      "trecho_id": "RISK_REGISTER.R06",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "só ficar disponível depois de D20",
          "motivo": "valor_divergente",
          "correto_seria": "só ficar disponível depois de D23"
        },
        {
          "citacao": "a montagem começaria depois da data planejada e o fim do projeto seria adiado na mesma medida.",
          "motivo": "premissa_alterada",
          "correto_seria": "isso só ocorreria se o acoplamento ficasse disponível depois de D23; então a montagem e o fim do projeto seriam adiados."
        }
      ],
      "observacao": "O acoplamento disponível em D18 tem 5 dias de folga até a montagem prevista para D23."
    },
    {
      "trecho_id": "DECISION_LOG.D01",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro de decisão passada."
    },
    {
      "trecho_id": "DECISION_LOG.D02",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro de decisão passada."
    },
    {
      "trecho_id": "DECISION_LOG.D03",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro de decisão passada."
    },
    {
      "trecho_id": "DECISION_LOG.D04",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro de decisão passada."
    }
  ]
}
